# Generated by Selenium IDE / Pytest for SGCS Project
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class TestMunicipalNotices:
    def setup_method(self, method):
        # Configure Chrome WebDriver
        options = webdriver.ChromeOptions()
        options.add_argument("--start-maximized")
        self.driver = webdriver.Chrome(options=options)
        self.wait = WebDriverWait(self.driver, 10)  # Explicit wait

    def teardown_method(self, method):
        self.driver.quit()

    def test_view_notices(self):
        # Step 1: Login as Citizen
        self.driver.get("http://localhost:5173/login")
        
        email_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "login-email-input"))
        )
        email_field.clear()
        email_field.send_keys("citizen@example.com")

        password_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "login-password-input"))
        )
        password_field.clear()
        password_field.send_keys("Citizen@123")

        login_btn = self.wait.until(
            EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))
        )
        login_btn.click()

        self.wait.until(EC.url_contains("/dashboard"))

        # Step 2: Navigate to Notices & Announcements page
        self.driver.get("http://localhost:5173/citizen/notices")

        # Step 3: Verify notices list heading is displayed
        notices_heading = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Ward Notices & Bulletins')]"))
        )
        assert notices_heading.is_displayed(), "Notices page heading not displayed!"

        # Step 4: Click on the municipal notice item card
        notice_card = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//*[contains(text(), 'Water Supply Maintenance') or contains(@class, 'notice-title')]"))
        )
        self.driver.execute_script("arguments[0].click();", notice_card)

        # Step 5: Verify notice details dialog modal is opened
        modal_title = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//div[@role='dialog']//*[contains(text(), 'Water Supply') or contains(text(), 'Maintenance')]"))
        )
        assert modal_title.is_displayed(), "Notice details modal was not displayed!"
        time.sleep(3)

if __name__ == "__main__":
    pytest.main(["-v", __file__])
